<?php
/**  * Service Parts Mapping API  * Handles dynamic service-parts mapping for Job Orders  */  require_once __DIR__ . '/../lib.php';
require_once __DIR__ . '/../../public/db_connect.php';  header('Content-Type: application/json');
header('Access-Control-Allow-Origin: *');
header('Access-Control-Allow-Methods: GET, POST, PUT, DELETE');
header('Access-Control-Allow-Headers: Content-Type, Authorization');  // Enable error reporting for debugging
error_reporting(E_ALL);
ini_set('display_errors', 1);  try {  $pdo = getPDO();  // Handle different HTTP methods  $method = $_SERVER['REQUEST_METHOD'];  switch ($method) {  case 'GET':  handleGetRequest($pdo);  break;  case 'POST':  handlePostRequest($pdo);  break;  case 'PUT':  handlePutRequest($pdo);  break;  case 'DELETE':  handleDeleteRequest($pdo);  break;  default:  http_response_code(405);  echo json_encode(['error' => 'Method not allowed']);  break;  }  } catch (Exception $e) {  http_response_code(500);  echo json_encode([  'error' => 'Internal server error',  'message' => $e->getMessage()  ]);
}  /**  * Handle GET requests  */
function handleGetRequest($pdo) {  $action = $_GET['action'] ?? '';  switch ($action) {  case 'get_services':  getServices($pdo);  break;  case 'get_parts_by_service':  getPartsByService($pdo);  break;  case 'get_all_parts':  getAllParts($pdo);  break;  case 'get_service_parts_mapping':  getServicePartsMapping($pdo);  break;  case 'search_parts':  searchParts($pdo);  break;  default:  http_response_code(400);  echo json_encode(['error' => 'Invalid action']);  break;  }
}  /**  * Handle POST requests  */
function handlePostRequest($pdo) {  $action = $_POST['action'] ?? '';  switch ($action) {  case 'add_service_part_mapping':  addServicePartMapping($pdo);  break;  case 'update_service_part_mapping':  updateServicePartMapping($pdo);  break;  default:  http_response_code(400);  echo json_encode(['error' => 'Invalid action']);  break;  }
}  /**  * Get all active service types  */
function getServices($pdo) {  try {  $stmt = $pdo->prepare("  SELECT id, service_key, service_name, base_rate_per_hour, icon_class, color_class,  allows_custom_input, sort_order  FROM job_order_service_types  WHERE active = TRUE  ORDER BY sort_order, service_name  ");  $stmt->execute();  $services = $stmt->fetchAll(PDO::FETCH_ASSOC);  echo json_encode([  'success' => true,  'data' => $services  ]);  } catch (Exception $e) {  http_response_code(500);  echo json_encode([  'success' => false,  'error' => 'Failed to fetch services: ' . $e->getMessage()  ]);  }
}  /**  * Get parts for specific service(s)  */
function getPartsByService($pdo) {  $service_ids = $_GET['service_ids'] ?? '';  if (empty($service_ids)) {  http_response_code(400);  echo json_encode([  'success' => false,  'error' => 'Service IDs are required'  ]);  return;  }  try {  // Handle both single ID and comma-separated IDs  $service_id_array = explode(',', $service_ids);  $placeholders = str_repeat('?,', count($service_id_array) - 1) . '?';  // First try the required_parts system (for calibration parts)  $stmt = $pdo->prepare("  SELECT DISTINCT  rpm.id,  rpm.part_name,  rpm.part_category,  NULL as part_code,  COALESCE(ip.unit_cost, 0) as unit_cost,  0 as current_stock,  0 as min_stock_level,  rpm.unit_of_measure,  rpm.is_merchandise,  rpm.default_quantity,  strp.is_default_selected as is_required,  strp.sort_order,  GROUP_CONCAT(jost.service_name ORDER BY jost.sort_order) as service_names  FROM required_parts_master rpm  JOIN service_type_required_parts strp ON rpm.id = strp.part_id  JOIN job_order_service_types jost ON strp.service_type_key = jost.service_key  LEFT JOIN inventory_products ip ON rpm.inventory_product_id = ip.id  WHERE strp.service_type_key IN ($placeholders)  AND rpm.active = TRUE  AND jost.active = TRUE  GROUP BY rpm.id, rpm.part_name, rpm.part_category, rpm.unit_of_measure, rpm.is_merchandise,  rpm.default_quantity, strp.is_default_selected, strp.sort_order, ip.unit_cost  ORDER BY strp.is_default_selected DESC, strp.sort_order, rpm.part_name  ");  $stmt->execute($service_id_array);  $parts = $stmt->fetchAll(PDO::FETCH_ASSOC);  // If no parts found in required_parts, try service_type_inventory_mapping  if (empty($parts)) {  $stmt = $pdo->prepare("  SELECT DISTINCT  NULL as id,  stim.required_part as part_name,  stim.part_category,  NULL as part_code,  0 as unit_cost,  0 as current_stock,  0 as min_stock_level,  'pc' as unit_of_measure,  1 as is_merchandise,  1 as default_quantity,  1 as is_required,  stim.sort_order,  GROUP_CONCAT(jt.service_name ORDER BY jt.sort_order) as service_names  FROM service_type_inventory_mapping stim  JOIN job_order_service_types jt ON stim.service_type = jt.service_key  WHERE jt.service_key IN ($placeholders)  AND jt.active = TRUE  GROUP BY stim.required_part, stim.part_category, stim.sort_order, jt.service_name  ORDER BY stim.sort_order, stim.required_part  ");  $stmt->execute($service_id_array);  $parts = $stmt->fetchAll(PDO::FETCH_ASSOC);  }  // If still no parts, try the old parts_inventory system  if (empty($parts)) {  $stmt = $pdo->prepare("  SELECT DISTINCT  pi.id,  pi.part_name,  pi.part_category,  pi.part_code,  pi.unit_cost,  pi.current_stock,  pi.min_stock_level,  pi.unit_of_measure,  pi.is_merchandise,  spm.default_quantity,  spm.is_required,  spm.sort_order,  GROUP_CONCAT(jt.service_name ORDER BY jt.sort_order) as service_names  FROM parts_inventory pi  JOIN service_parts_map spm ON pi.id = spm.part_id  JOIN job_order_service_types jt ON spm.service_id = jt.id  WHERE spm.service_id IN ($placeholders)  AND pi.is_active = TRUE  AND jt.active = TRUE  GROUP BY pi.id, pi.part_name, pi.part_category, pi.part_code, pi.unit_cost,  pi.current_stock, pi.min_stock_level, pi.unit_of_measure, pi.is_merchandise,  spm.default_quantity, spm.is_required, spm.sort_order  ORDER BY spm.is_required DESC, spm.sort_order, pi.part_name  ");  $stmt->execute($service_id_array);  $parts = $stmt->fetchAll(PDO::FETCH_ASSOC);  }  // Add stock status  foreach ($parts as &$part) {  $part['stock_status'] = getStockStatus($part['current_stock'], $part['min_stock_level']);  $part['in_inventory'] = $part['current_stock'] > 0;  // Ensure default_quantity is set  if (!isset($part['default_quantity']) || $part['default_quantity'] === null) {  $part['default_quantity'] = 1;  }  }  echo json_encode([  'success' => true,  'data' => $parts,  'count' => count($parts)  ]);  } catch (Exception $e) {  http_response_code(500);  echo json_encode([  'success' => false,  'error' => 'Failed to fetch parts: ' . $e->getMessage()  ]);  }
}  /**  * Get all parts inventory  */
function getAllParts($pdo) {  $category = $_GET['category'] ?? '';  $search = $_GET['search'] ?? '';  try {  $sql = "  SELECT id, part_name, part_category, part_code, unit_cost, current_stock,  min_stock_level, unit_of_measure, is_merchandise  FROM parts_inventory  WHERE is_active = TRUE  ";  $params = [];  // Add category filter  if (!empty($category)) {  $sql .= " AND part_category = ?";  $params[] = $category;  }  // Add search filter  if (!empty($search)) {  $sql .= " AND (part_name LIKE ? OR part_code LIKE ?)";  $search_param = '%' . $search . '%';  $params[] = $search_param;  $params[] = $search_param;  }  $sql .= " ORDER BY part_category, part_name";  $stmt = $pdo->prepare($sql);  $stmt->execute($params);  $parts = $stmt->fetchAll(PDO::FETCH_ASSOC);  // Add stock status  foreach ($parts as &$part) {  $part['stock_status'] = getStockStatus($part['current_stock'], $part['min_stock_level']);  $part['in_inventory'] = $part['current_stock'] > 0;  }  echo json_encode([  'success' => true,  'data' => $parts,  'count' => count($parts)  ]);  } catch (Exception $e) {  http_response_code(500);  echo json_encode([  'success' => false,  'error' => 'Failed to fetch parts: ' . $e->getMessage()  ]);  }
}  /**  * Get complete service-parts mapping  */
function getServicePartsMapping($pdo) {  try {  $stmt = $pdo->prepare("  SELECT  jt.id as service_id,  jt.service_key,  jt.service_name,  jt.base_rate_per_hour,  jt.icon_class,  jt.color_class,  pi.id as part_id,  pi.part_name,  pi.part_category,  pi.part_code,  pi.unit_cost,  pi.current_stock,  pi.min_stock_level,  pi.unit_of_measure,  pi.is_merchandise,  spm.default_quantity,  spm.is_required,  spm.sort_order  FROM job_order_service_types jt  LEFT JOIN service_parts_map spm ON jt.id = spm.service_id  LEFT JOIN parts_inventory pi ON spm.part_id = pi.id  WHERE jt.active = TRUE  AND (pi.is_active = TRUE OR pi.id IS NULL)  ORDER BY jt.sort_order, spm.sort_order, pi.part_name  ");  $stmt->execute();  $mappings = $stmt->fetchAll(PDO::FETCH_ASSOC);  // Group by service  $grouped_mappings = [];  foreach ($mappings as $mapping) {  $service_id = $mapping['service_id'];  if (!isset($grouped_mappings[$service_id])) {  $grouped_mappings[$service_id] = [  'service_id' => $mapping['service_id'],  'service_key' => $mapping['service_key'],  'service_name' => $mapping['service_name'],  'base_rate_per_hour' => $mapping['base_rate_per_hour'],  'icon_class' => $mapping['icon_class'],  'color_class' => $mapping['color_class'],  'parts' => []  ];  }  if ($mapping['part_id']) {  $grouped_mappings[$service_id]['parts'][] = [  'part_id' => $mapping['part_id'],  'part_name' => $mapping['part_name'],  'part_category' => $mapping['part_category'],  'part_code' => $mapping['part_code'],  'unit_cost' => $mapping['unit_cost'],  'current_stock' => $mapping['current_stock'],  'min_stock_level' => $mapping['min_stock_level'],  'unit_of_measure' => $mapping['unit_of_measure'],  'is_merchandise' => $mapping['is_merchandise'],  'default_quantity' => $mapping['default_quantity'],  'is_required' => $mapping['is_required'],  'sort_order' => $mapping['sort_order'],  'stock_status' => getStockStatus($mapping['current_stock'], $mapping['min_stock_level']),  'in_inventory' => $mapping['current_stock'] > 0  ];  }  }  echo json_encode([  'success' => true,  'data' => array_values($grouped_mappings),  'total_services' => count($grouped_mappings)  ]);  } catch (Exception $e) {  http_response_code(500);  echo json_encode([  'success' => false,  'error' => 'Failed to fetch mapping: ' . $e->getMessage()  ]);  }
}  /**  * Search parts by name or code  */
function searchParts($pdo) {  $query = $_GET['q'] ?? '';  if (empty($query)) {  http_response_code(400);  echo json_encode([  'success' => false,  'error' => 'Search query is required'  ]);  return;  }  try {  $stmt = $pdo->prepare("  SELECT id, part_name, part_category, part_code, unit_cost, current_stock,  min_stock_level, unit_of_measure, is_merchandise  FROM parts_inventory  WHERE is_active = TRUE  AND (part_name LIKE ? OR part_code LIKE ?)  ORDER BY  CASE  WHEN part_name LIKE ? THEN 1  WHEN part_code LIKE ? THEN 2  ELSE 3  END,  part_name  LIMIT 20  ");  $search_param = '%' . $query . '%';  $exact_param = $query . '%';  $stmt->execute([$search_param, $search_param, $exact_param, $exact_param]);  $parts = $stmt->fetchAll(PDO::FETCH_ASSOC);  // Add stock status  foreach ($parts as &$part) {  $part['stock_status'] = getStockStatus($part['current_stock'], $part['min_stock_level']);  $part['in_inventory'] = $part['current_stock'] > 0;  }  echo json_encode([  'success' => true,  'data' => $parts,  'count' => count($parts),  'query' => $query  ]);  } catch (Exception $e) {  http_response_code(500);  echo json_encode([  'success' => false,  'error' => 'Failed to search parts: ' . $e->getMessage()  ]);  }
}  /**  * Add new service-part mapping  */
function addServicePartMapping($pdo) {  $service_id = $_POST['service_id'] ?? '';  $part_id = $_POST['part_id'] ?? '';  $default_quantity = $_POST['default_quantity'] ?? 1;  $is_required = $_POST['is_required'] ?? 'true';  $sort_order = $_POST['sort_order'] ?? 0;  if (empty($service_id) || empty($part_id)) {  http_response_code(400);  echo json_encode([  'success' => false,  'error' => 'Service ID and Part ID are required'  ]);  return;  }  try {  $stmt = $pdo->prepare("  INSERT INTO service_parts_map (service_id, part_id, default_quantity, is_required, sort_order)  VALUES (?, ?, ?, ?, ?)  ON DUPLICATE KEY UPDATE  default_quantity = VALUES(default_quantity),  is_required = VALUES(is_required),  sort_order = VALUES(sort_order),  updated_at = CURRENT_TIMESTAMP  ");  $stmt->execute([  $service_id,  $part_id,  $default_quantity,  $is_required === 'true' ? 1 : 0,  $sort_order  ]);  echo json_encode([  'success' => true,  'message' => 'Service-part mapping added successfully'  ]);  } catch (Exception $e) {  http_response_code(500);  echo json_encode([  'success' => false,  'error' => 'Failed to add mapping: ' . $e->getMessage()  ]);  }
}  /**  * Update existing service-part mapping  */
function updateServicePartMapping($pdo) {  $mapping_id = $_POST['mapping_id'] ?? '';  $default_quantity = $_POST['default_quantity'] ?? 1;  $is_required = $_POST['is_required'] ?? 'true';  $sort_order = $_POST['sort_order'] ?? 0;  if (empty($mapping_id)) {  http_response_code(400);  echo json_encode([  'success' => false,  'error' => 'Mapping ID is required'  ]);  return;  }  try {  $stmt = $pdo->prepare("  UPDATE service_parts_map  SET default_quantity = ?, is_required = ?, sort_order = ?, updated_at = CURRENT_TIMESTAMP  WHERE id = ?  ");  $stmt->execute([  $default_quantity,  $is_required === 'true' ? 1 : 0,  $sort_order,  $mapping_id  ]);  echo json_encode([  'success' => true,  'message' => 'Service-part mapping updated successfully'  ]);  } catch (Exception $e) {  http_response_code(500);  echo json_encode([  'success' => false,  'error' => 'Failed to update mapping: ' . $e->getMessage()  ]);  }
}  /**  * Get stock status based on current and minimum levels  */
function getStockStatus($current_stock, $min_stock_level) {  if ($current_stock == 0) {  return 'out_of_stock';  } elseif ($current_stock <= $min_stock_level) {  return 'low_stock';  } else {  return 'in_stock';  }
}  /**  * Handle PUT requests (for future enhancements)  */
function handlePutRequest($pdo) {  http_response_code(501);  echo json_encode(['error' => 'PUT method not implemented yet']);
}  /**  * Handle DELETE requests (for future enhancements)  */
function handleDeleteRequest($pdo) {  http_response_code(501);  echo json_encode(['error' => 'DELETE method not implemented yet']);
}
?>
